#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_picture_score_zero(void) {
    // Setup: capture stdout to verify output
    stdout_capture_t *cap = capture_stdout_start();
    TEST_ASSERT_NOT_NULL(cap);

    // Test: call picture with score = 0 (target path)
    picture(0);

    // Stop capturing and get output
    char *output = capture_stdout_stop(cap);
    TEST_ASSERT_NOT_NULL(output);

    // Assert: For score 0, the function should print nothing (empty output)
    // The case 0 has only a break statement, no printf.
    TEST_ASSERT_EQUAL_STRING("", output);

    // Cleanup
    free(output);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_picture_score_zero);
    return UNITY_END();
}

